sys_script_client.script:
function onLoad() {

    // Check allowed roles
    var allowedRole = g_user.hasRole('admin') ||g_user.hasRole('x_snc_college_pl_0.placement_admin')||g_user.hasRole('x_snc_college_pl_0.placement_officer');

    // If this is a new record, hide the entire Information section
    if (g_form.isNewRecord()) {
        g_form.setSectionDisplay('information', false);
        return;
    }

    // After Submit:
    // Show Information section only to Admin and Placement Officer
    if (allowedRole) {
        g_form.setSectionDisplay('information', true);
    } else {
        g_form.setSectionDisplay('information', false);
    }
}
